require __DIR__.'/common.php';devize_ready($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){deviz_check();$id=(int)($_POST['id']??0);$s=$pdo->prepare('DELETE FROM eco_devize WHERE id=?');$s->execute([$id]);header('Location: /devize/');exit;}
$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT d.*,COALESCE(SUM(i.quantity*i.unit_price),0) total,MAX(d.vat_rate) vat_rate,COUNT(i.id) positions FROM eco_devize d LEFT JOIN eco_devize_items i ON i.deviz_id=d.id WHERE d.number LIKE ? OR d.title LIKE ? GROUP BY d.id ORDER BY d.id DESC');$s->execute(['%'.$q.'%','%'.$q.'%']);$rows=$s->fetchAll();require __DIR__.'/../includes/header.php';
?>
<style>.dv{max-width:1150px;margin:auto}.dv-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:22px}.dv h1{font-size:27px;color:#172033;margin:0 0 5px}.dv p{color:#778396;margin:0}.dv .button{display:inline-block;background:#1769aa;color:white;padding:12px 18px;border-radius:10px;text-decoration:none;font-weight:700}.dv input{border:1px solid #dce4ed;border-radius:10px;padding:12px;max-width:100%;width:340px}.dv table{width:100%;border-collapse:collapse;background:white;border-radius:12px;overflow:hidden}.dv td,.dv th{padding:15px;border-bottom:1px solid #edf0f4;text-align:left}.dv th{background:#f4f7fa;font-size:12px}.dv a{color:#1769aa;font-weight:650}.dv .actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.dv .del{border:0;background:transparent;color:#c33;cursor:pointer}.dv .tablewrap{overflow-x:auto;border-radius:12px}@media(max-width:680px){.dv table,.dv tbody,.dv tr,.dv td{display:block}.dv thead{display:none}.dv tr{background:white;border:1px solid #e8edf2;border-radius:12px;margin:10px 0;padding:12px}.dv td{padding:6px;border:0}.dv .dv-head{align-items:stretch}.dv .button{ text-align:center}.dv input{width:100%}}</style>
<section class="dv"><div class="dv-head"><div><h1>Devize</h1><p>Devize independente, fără asociere cu un client.</p></div><a class="button" href="/devize/edit.php">+ Deviz nou</a></div><form method="get" style="margin-bottom:16px"><input name="q" value="<?=e($q)?>" placeholder="Caută după număr sau titlu" aria-label="Caută deviz"></form><div class="tablewrap"><table><thead><tr><th>Deviz</th><th>Data</th><th>Poziții</th><th>Total fără TVA</th><th>TVA</th><th>Acțiuni</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="/devize/edit.php?id=<?=(int)$r['id']?>"><?=e($r['number'])?></a><?php if($r['title']!==''):?><div style="font-size:12px;color:#778396"><?=e($r['title'])?></div><?php endif;?></td><td><?=e(date('d.m.Y',strtotime($r['created_at'])))?></td><td><?=(int)$r['positions']?></td><td><b><?=deviz_money($r['total'])?> EUR</b></td><td><?php if($r['vat_rate']!==null):?><b><?=deviz_money($r['total']*(1+(float)$r['vat_rate']/100))?> EUR</b><div style="font-size:11px;color:#73859c">cu TVA <?=deviz_money($r['vat_rate'])?>%</div><?php else:?>—<?php endif;?></td><td><div class="actions"><a href="/devize/edit.php?id=<?=(int)$r['id']?>">Editează</a><a href="/devize/pdf.php?id=<?=(int)$r['id']?>" target="_blank">PDF</a><form method="post" onsubmit="return confirm('Ștergi definitiv devizul?')"><input type="hidden" name="csrf" value="<?=deviz_token()?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="del">Șterge</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Nu există devize. Creează primul deviz.</td></tr><?php endif;?></tbody></table></div></section>
